css:
.container {
  display: grid;
  place-content: center;
  width: 100%;
  height: 100%;
  background: #e0e0e0;
}

.comic-radio-group {
  --bg: #ffd700;
  --text-light: #ffffff;
  --text-dark: #000000;

  display: flex;
  position: relative;
  background: var(--bg);
  border-radius: 12px;
  border: 4px solid var(--text-dark);
  box-shadow: 8px 8px 0px var(--text-dark);
  overflow: hidden;
  width: fit-content;
  font-family: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
  font-style: italic;
  font-weight: 500;
}

.comic-radio-group input {
  display: none;
}

.comic-radio-group label {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 100px;
  font-size: 24px;
  padding: 0.8rem 1.6rem;
  cursor: pointer;
  letter-spacing: 1px;
  color: var(--text-dark);
  position: relative;
  z-index: 2;
  transition: color 0.3s ease-in-out;
  text-shadow:
    -1px -1px 0 var(--text-light),
    1px -1px 0 var(--text-light),
    -1px 1px 0 var(--text-light),
    1px 1px 0 var(--text-light);
}

.comic-radio-group input:checked + label {
  color: var(--text-light);
  text-shadow:
    -2px -2px 0 var(--text-dark),
    2px -2px 0 var(--text-dark),
    -2px 2px 0 var(--text-dark),
    2px 2px 0 var(--text-dark);
}

.comic-glider {
  position: absolute;
  top: 0;
  bottom: 0;
  width: calc(100% / 3);
  border-radius: 8px;
  z-index: 1;

  transition:
    transform 0.5s cubic-bezier(0.37, 1.95, 0.66, 0.56),
    background 0.4s ease-in-out,
    box-shadow 0.4s ease-in-out;
  border-right: 4px solid var(--text-dark);
  border-left: 4px solid var(--text-dark);
}

#comic-pow:checked ~ .comic-glider {
  transform: translateX(0%);
  background-color: #e74c3c;
  background-image: radial-gradient(
    circle at 4px 4px,
    #c0392b 2px,
    transparent 0
  );
  background-size: 8px 8px;
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.5);
}

#comic-bam:checked ~ .comic-glider {
  transform: translateX(100%);
  background-color: #3498db;
  background-image: radial-gradient(
    circle at 4px 4px,
    #2980b9 2px,
    transparent 0
  );
  background-size: 8px 8px;
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.5);
}

#comic-zap:checked ~ .comic-glider {
  transform: translateX(200%);
  background-color: #2ecc71;
  background-image: radial-gradient(
    circle at 4px 4px,
    #27ae60 2px,
    transparent 0
  );
  background-size: 8px 8px;
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.5);
}
